def read_integer(environment, key, default, minimum, maximum):
    value = environment.get(key)
    if value is None:
        return default

    try:
        trimmed_value = str(value).strip()
        if not trimmed_value:
            raise ValueError("Environment value for key is empty.")

        int_value = int(trimmed_value)
    except ValueError as e:
        raise ValueError(f"Invalid integer format for key '{key}': {value}") from e

    if not (minimum <= int_value <= maximum):
        raise ValueError(f"Value {int_value} for key '{key}' is outside the allowed range [{minimum}, {maximum}]")

    return int_value

