def retry_count(total_attempts, current_attempt):
    if total_attempts < 1:
        raise ValueError("total_attempts must be at least 1")
    if not (1 <= current_attempt <= total_attempts):
        raise ValueError(f"current_attempt must be between 1 and {total_attempts}")
    return total_attempts - current_attempt

