class Job:
    def __init__(self):
        self.state = 'new'

    def transition(self, target):
        current_state = self.state

        if current_state == 'new' and target == 'queued':
            self.state = 'queued'
            return self.state
        elif current_state == 'queued' and target == 'running':
            self.state = 'running'
            return self.state
        elif current_state == 'running' and (target == 'succeeded' or target == 'failed'):
            self.state = target
            return self.state
        elif current_state == 'failed' and target == 'queued':
            self.state = 'queued'
            return self.state
        else:
            raise ValueError(f"Invalid transition from {current_state} to {target}")

