def retry_count(total_attempts, current_attempt):
    if total_attempts < 1:
        raise ValueError("total_attempts must be at least 1")
    if not (1 <= current_attempt <= total_attempts):
        raise ValueError("current_attempt must be between 1 and total_attempts inclusive")
    return total_attempts - current_attempt

def transfer(balances, source, target, amount):
    if amount <= 0:
        raise ValueError("Transfer amount must be positive.")

    if source == target:
        raise ValueError("Source and target accounts must be distinct.")

    if source not in balances or target not in balances:
        raise ValueError("One or both accounts do not exist.")

    if balances[source] < amount:
        raise ValueError("Insufficient funds in source account.")

    balances[source] -= amount
    balances[target] += amount
    return balances

