def parse_properties(text):
    properties = {}
    for i, line in enumerate(text.splitlines()):
        line = line.strip()
        if not line or line.startswith('#'):
            continue

        if '=' in line:
            parts = line.split('=', 1)
            key = parts[0].strip()
            value = parts[1].strip()

            if key:
                properties[key] = value
            else:
                # Reject lines where the key is empty after stripping
                raise ValueError(f"Malformed property line found on line {i + 1}: {line}")
        else:
            # Reject malformed non-comment lines
            raise ValueError(f"Malformed property line found on line {i + 1}: {line}")

    return properties

def parse_fixed_width(text, widths):
    result = []
    total_width = sum(widths)
    for line in text.splitlines():
        line = line.strip()
        if not line:
            continue

        if len(line) != total_width:
            continue

        fields = []
        for width in widths:
            start = len(fields) * width
            end = start + width
            fields.append(line[start:end].strip())

        result.append(fields)
    return result

