def transfer(balances, source, target, amount):
    if amount <= 0:
        raise ValueError("Transfer amount must be positive.")

    if source == target:
        raise ValueError("Source and target accounts must be distinct.")

    if source not in balances:
        raise ValueError(f"Source account {source} not found.")

    if target not in balances:
        raise ValueError(f"Target account {target} not found.")

    if balances[source] < amount:
        raise ValueError("Insufficient funds in source account.")

    balances[source] -= amount
    balances[target] += amount
    return balances

