def read_integer(environment, key, default, minimum, maximum):
    value = environment.get(key)

    if value is None:
        return default

    # Trim the value
    trimmed_value = str(value).strip()

    if not trimmed_value:
        raise ValueError(f"Environment value for key '{key}' is empty or whitespace.")

    try:
        int_value = int(trimmed_value)
    except ValueError:
        raise ValueError(f"Value for key '{key}' ('{trimmed_value}') is not a valid integer.")

    if not (minimum <= int_value <= maximum):
        raise ValueError(f"Value for key '{key}' ({int_value}) is outside the allowed range [{minimum}, {maximum}].")

    return int_value

