class Job:
    def __init__(self):
        self.state = 'new'
    def transition(self, target):
        current_state = self.state
        valid_transitions = {
            'new': ['queued'],
            'queued': ['running'],
            'running': ['succeeded', 'failed'],
            'failed': ['queued']
        }

        if target in valid_transitions.get(current_state, []):
            self.state = target
            return self.state
        else:
            raise ValueError(f"Invalid transition from {current_state} to {target}")

