def extract_items(payload):
    if isinstance(payload, list):
        return list(payload)

    if isinstance(payload, dict):
        if 'items' in payload:
            items = payload['items']
            if isinstance(items, list):
                return list(items)
            else:
                raise ValueError("The 'items' key in the dictionary must contain a list.")
        else:
            raise ValueError("Dictionary payload must contain an 'items' key.")

    raise ValueError("Payload must be a list or a dictionary.")

def validate_headers(headers):
    seen = set()
    result = []
    for header in headers:
        normalized_header = header.strip().lower()
        if not normalized_header:
            continue
        if normalized_header not in seen:
            seen.add(normalized_header)
            result.append(normalized_header)
    return result

