def test_valid_transfer_updates_both_accounts():
    balances = {'a': 10, 'b': 2}
    assert transfer(balances, 'a', 'b', 4) == {'a': 6, 'b': 6}

def test_invalid_transfers_leave_ledger_unchanged():
    for source, target, amount in [('a', 'b', 0), ('a', 'b', 11), ('x', 'b', 1), ('a', 'a', 1)]:
        balances = {'a': 10, 'b': 2}
        with pytest.raises(ValueError):
            transfer(balances, source, target, amount)
        assert balances == {'a': 10, 'b': 2}

