class Job:
    def __init__(self):
        self.state = 'new'
    def transition(self, target):
        current_state = self.state
        valid_transitions = {
            'new': ['queued'],
            'queued': ['running'],
            'running': ['succeeded', 'failed'],
            'failed': ['queued']
        }

        if target not in valid_transitions.get(current_state, []):
            raise ValueError(f"Invalid transition from {current_state} to {target}")

        self.state = target
        return self.state

